# Viva deep redo — slot R1 (part B): leprosy, cutaneous TB, HSV, molluscum, varicella (5 cases)
# Own words. Question topics guided by the previous-year question book (Sahana P Raju); facts from IADVL 5e
# (ch. 16 Cutaneous tuberculosis, leprosy section, viral infections) + current NLEP / NTEP guidance.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Hansen's disease (leprosy)", src=f"{PYQ}; {IA} (leprosy chapters); NLEP revised MDT guidance effective 1 April 2025; WHO disability grading",
 qa=[
 ("Define leprosy.", ["Chronic granulomatous infection by Mycobacterium leprae (and M. lepromatosis) that mainly affects skin and peripheral nerves, also eyes, nasal mucosa, testes, bones; clinical spectrum decided by host cell-mediated immunity"]),
 ("Describe the organism.", ["Acid-fast (weaker than M. tuberculosis — decolorise with 5% sulphuric acid), Gram-positive, obligate intracellular bacillus; prefers Schwann cells and macrophages", "Generation time ~12–14 days (slowest known); optimum 30–33 °C → cooler parts of body affected (ear lobes, nose, testes, superficial nerves)", "Not cultivable in vitro; grows in mouse foot-pad (Shepard) and nine-banded armadillo", "Cell wall: phenolic glycolipid-1 (PGL-1, species specific — binds laminin-α2 of Schwann cell basal lamina), lipoarabinomannan; genome shows massive gene decay (only ~half functional genes)"]),
 ("Transmission and incubation period?", ["Main route: nasal droplets from untreated multibacillary patients → upper respiratory mucosa; less often broken skin; rarely transplacental, insect, armadillo (zoonosis in USA)", "Incubation: average 2–5 years for PB, 8–12 years for MB (range months to decades)", "Most exposed people never develop disease (high natural resistance); household contacts of MB patients have the highest risk"]),
 ("What are the cardinal signs of leprosy (NLEP)?", ["1) Hypopigmented or erythematous skin patch with definite loss of sensation", "2) Thickened or enlarged peripheral nerve with loss of sensation and/or weakness of muscles supplied by it", "3) Acid-fast bacilli in slit-skin smear", "Any one sign is enough to diagnose leprosy"]),
 ("Give the Ridley–Jopling classification and the immunological basis.", ["TT – BT – BB – BL – LL (+ indeterminate outside the spectrum; pure neuritic separately)", "TT pole: strong Th1 (IFN-γ, IL-2), few bacilli, lepromin positive; LL pole: Th2 (IL-4, IL-10), anergy to M. leprae, plenty of bacilli, lepromin negative", "Borderline groups are immunologically unstable → shift (upgrade/downgrade) and type 1 reactions"]),
 ("Give the WHO / NLEP operational classification.", ["Paucibacillary (PB): 1–5 skin lesions, no nerve involvement, smear negative", "Multibacillary (MB): ≥6 skin lesions, OR any nerve involvement (NLEP 2025: any nerve involvement = MB), OR positive slit-skin smear irrespective of lesions", "When in doubt classify as MB"]),
 ("Compare TT, BT, BB, BL and LL clinically.", ["TT: 1–3 well-defined dry, scaly, anaesthetic plaques with raised edges, hair loss, one thickened nerve near the lesion", "BT: few–many (≤10) asymmetrical lesions with satellite lesions and irregular edges, sensory loss, several nerves asymmetrically thickened", "BB: many 'punched-out', inverted-saucer or Swiss-cheese lesions with sloping outer edge; unstable", "BL: many lesions, roughly symmetrical, some sensation preserved, many nerves, early nodules", "LL: innumerable symmetrical shiny macules/papules/nodules, diffuse infiltration, leonine facies, madarosis, ear lobe thickening, glove-and-stocking anaesthesia, late nerve damage, systemic involvement"]),
 ("What is indeterminate leprosy?", ["Earliest form: one or few vague hypopigmented macules with ill-defined edges and doubtful/slight sensory loss, usually in children; smear negative; nerves not thickened", "Histology: perineural/peri-appendageal lymphocytes, rare bacilli in nerve", "May heal spontaneously or progress to any group"]),
 ("What is pure neuritic leprosy?", ["Nerve involvement (thickening, sensory/motor loss) without any skin lesion; ~5–10% in India", "Diagnosis: nerve biopsy (sural or radial cutaneous) or FNAC; treat as MB"]),
 ("Which nerves do you palpate and where?", ["Supraorbital, great auricular (neck, across sternomastoid on turning head), ulnar (above medial epicondyle), median (wrist, medial to palmaris longus), radial cutaneous (lateral border of radius at wrist), radial (spiral groove), common peroneal (behind fibular head), superficial peroneal (dorsum of foot), sural, posterior tibial (behind medial malleolus)", "Note: thickening, tenderness, consistency, nodules/abscess; compare both sides"]),
 ("Describe the deformities in leprosy and classify them.", ["Primary (due to disease): madarosis, leonine facies, nasal collapse (saddle nose), lagophthalmos, claw hand, foot drop, ape thumb", "Secondary (due to anaesthesia/neglect): ulcers, shortening and absorption of digits, contractures, Charcot joints", "Ulnar claw (ring and little finger), median + ulnar = complete claw with ape-thumb (thenar wasting), radial = wrist drop (rare), common peroneal = foot drop, posterior tibial = claw toes and plantar anaesthesia, facial = lagophthalmos, trigeminal = corneal anaesthesia"]),
 ("Grade disability (WHO).", ["Hands and feet: Grade 0 — no anaesthesia, no visible deformity; Grade 1 — anaesthesia, no visible deformity; Grade 2 — visible deformity or damage (ulcers, claw, foot drop, resorption)", "Eyes: Grade 0 normal; Grade 1 — eye problems due to leprosy but vision not severely affected (≥6/60); Grade 2 — lagophthalmos, iridocyclitis, corneal opacity, vision <6/60", "EHF score: sum of grades of 2 eyes, 2 hands, 2 feet (0–12) — better for monitoring"]),
 ("How do you do and read a slit-skin smear?", ["Sites: both ear lobes, forehead/eyebrow, active edge of lesions (usually 4–6 sites); blanch skin by pinching, 5 mm long 2–3 mm deep slit, scrape dermal fluid, smear, fix, Ziehl–Neelsen with 5% H2SO4", "Bacteriological index (Ridley log scale, 0 to 6+): 1+ = 1–10 bacilli in 100 fields … 6+ = >1000 per field; average of sites", "Morphological index: % of solid (uniformly stained, viable) bacilli — falls quickly with treatment; BI falls ~0.6–1 log per year"]),
 ("What is the Fite–Faraco stain?", ["Modified acid-fast stain using peanut oil–xylene to protect the fragile lipid coat of M. leprae in tissue sections — better than ZN for biopsies"]),
 ("Describe the histopathology across the spectrum.", ["TT: well-formed epithelioid granulomas reaching up to epidermis, dense lymphocytic mantle, nerves destroyed, no bacilli", "BT: granulomas with a narrow grenz zone sometimes absent, fewer lymphocytes, nerves swollen, AFB rare", "BB: diffuse epithelioid cells, no giant cells, few lymphocytes, moderate bacilli", "BL: macrophage granulomas with some foamy cells, lymphocytes, 'onion-skin' perineurium", "LL: clear grenz zone (Unna band), sheets of foamy Virchow (lepra) cells with globi, very few lymphocytes, many bacilli"]),
 ("What is the lepromin test? How is it read and what is its value?", ["Intradermal injection of 0.1 ml heat-killed M. leprae (Mitsuda/Dharmendra antigen)", "Early Fernandez reaction at 48–72 h (delayed hypersensitivity to soluble antigen); late Mitsuda reaction at 21–28 days (nodule ≥5 mm = positive; reflects ability to mount granulomatous CMI)", "Not diagnostic (positive in healthy people); used for classification and prognosis — negative in LL/BL"]),
 ("Other diagnostic tests?", ["Sensory testing: monofilaments (Semmes–Weinstein), ball-pen, temperature/pain tests", "Histamine test (incomplete triple response in anaesthetic patch — sensory nerve loss), sweat test with pilocarpine/starch-iodine (anhidrosis)", "Nerve conduction studies, high-resolution ultrasound of nerves", "Serology: anti-PGL-1 IgM (correlates with bacterial load; useful in MB and contact surveillance)", "PCR for M. leprae DNA (RLEP) — pure neuritic, paucibacillary, relapse; rpoB/folP/gyrA for drug resistance"]),
 ("What are lepra reactions? Compare type 1 and type 2.", ["Acute inflammatory episodes during otherwise chronic course, before, during or after MDT; main cause of nerve damage", "Type 1 (reversal reaction): delayed-type hypersensitivity (Th1 up), in borderline cases (BT, BB, BL); existing lesions become red, swollen, tender; new lesions; acute neuritis (pain, tenderness, new loss of function); oedema of hands/feet/face; little systemic upset", "Type 2 (erythema nodosum leprosum, ENL): immune-complex (type III) with neutrophils and high TNF-α, in BL/LL with high BI; crops of tender evanescent red nodules on normal skin, fever, malaise, neuritis, iridocyclitis, orchitis, arthritis, lymphadenitis, nephritis, dactylitis; often recurrent/chronic"]),
 ("How do you treat type 1 reaction?", ["Continue MDT; rest, splint affected nerves, analgesics", "Prednisolone 40 mg/day (≈1 mg/kg) tapering slowly: e.g. 40 mg ×2 wk, 30, 25, 20, 15, 10, 5 mg in 2–4 weekly steps — about 12 weeks for PB and 20–24 weeks for MB/neuritis", "Severe neuritis not responding: higher dose, then consider nerve decompression"]),
 ("How do you treat ENL?", ["Mild: NSAIDs, rest", "Moderate–severe: prednisolone 40–60 mg/day with taper (short course)", "Chronic/recurrent: clofazimine 100 mg three times daily up to 12 weeks then taper (total ≤12 months) — steroid-sparing, slow onset", "Thalidomide 100–400 mg/day (very effective; teratogenic — not in women of child-bearing age without strict contraception; neuropathy, thrombosis); pentoxifylline, methotrexate, minocycline also used"]),
 ("What is the Lucio phenomenon?", ["Occurs in untreated diffuse non-nodular lepromatous leprosy (Lucio–Latapi, 'lepra bonita' with smooth shiny skin) — Mexico/Central America", "Necrotising vasculitis by bacilli in endothelium → painful purpuric angular lesions becoming haemorrhagic bullae and ulcers on limbs, without fever", "Treat with MDT + steroids, wound care; may need exchange transfusion in severe cases"]),
 ("What is histoid leprosy?", ["Variant of LL (often after dapsone monotherapy or irregular treatment) with soft, shiny skin-coloured to red papules and nodules on apparently normal skin, especially over joints and back", "Histology: spindle-shaped histiocytes in a whorled/storiform pattern with huge numbers of bacilli (high BI) — a source of drug resistance and transmission"]),
 ("Name the other clinical variants.", ["Lazarine leprosy (ulcerating lesions in borderline cases without neuritis)", "Lepra bonita / Lucio leprosy, histoid, pure neuritic, conjugal leprosy (between spouses, low rate)", "Childhood leprosy (indicator of active transmission in the community)", "Leprosy in HIV (more type 1 reactions after ART — immune reconstitution)"]),
 ("What is the MDT regimen now (NLEP from 1 April 2025)?", ["Same 3 drugs for both PB and MB: rifampicin + clofazimine + dapsone; PB for 6 months, MB for 12 months", "Adult (>14 y): monthly supervised rifampicin 600 mg + clofazimine 300 mg; daily self-administered clofazimine 50 mg + dapsone 100 mg", "Child 10–14 y: rifampicin 450 mg + clofazimine 150 mg monthly; clofazimine 50 mg alternate days + dapsone 50 mg daily", "Child <10 y: by weight — rifampicin 10 mg/kg monthly, clofazimine 6 mg/kg monthly + 1 mg/kg alternate days, dapsone 2 mg/kg daily", "Blister packs: adult (red for MB), child (yellow); release from treatment after completing the course (PB in 6 within 9 months, MB in 12 within 18 months)"]),
 ("Mechanism of action and important side effects of MDT drugs.", ["Rifampicin: inhibits DNA-dependent RNA polymerase (rpoB) — kills 99.9% with one dose; red urine, hepatitis, flu-like syndrome/thrombocytopenia with intermittent dosing, enzyme inducer (reduces OCP and steroid efficacy)", "Dapsone: blocks folate synthesis (dihydropteroate synthase; folP); haemolysis (worse in G6PD deficiency), methaemoglobinaemia, agranulocytosis, dapsone hypersensitivity syndrome (~4–6 weeks; fever, rash, hepatitis, lymphadenopathy; HLA-B*13:01), neuropathy", "Clofazimine: binds mycobacterial DNA, anti-inflammatory; reddish-brown pigmentation and ichthyosis (reversible slowly), GI crystal deposition (abdominal pain), dry skin"]),
 ("Newer drugs / alternative regimens?", ["Ofloxacin/levofloxacin/moxifloxacin, minocycline, clarithromycin — for drug intolerance or resistance", "Rifampicin resistance: 24 months of daily clofazimine with two of ofloxacin/moxifloxacin, minocycline, clarithromycin (WHO)", "Rifapentine, bedaquiline under study"]),
 ("What is chemoprophylaxis of leprosy?", ["Single-dose rifampicin (SDR-PEP) to contacts of new cases after excluding leprosy and TB — adults 600 mg; children by age/weight (not under 2 years)", "Reduces risk in contacts by about 50–60% in the first 2 years (COLEP)", "Used under NLEP in contact tracing campaigns (LCDC)"]),
 ("Vaccines in leprosy?", ["BCG gives variable protection (≈ 26–50%); repeat BCG adds some", "Mycobacterium indicus pranii (MIP, formerly Mw) — immunotherapy with MDT and in contacts (Indian vaccine)", "LepVax (LEP-F1) in trials"]),
 ("Define relapse; differentiate it from type 1 reaction.", ["Relapse: re-appearance of disease activity after successful completion of MDT (new lesions, new nerve damage, rise in BI ≥2+ at any site)", "Reaction: sudden onset (days), within ~6 months of stopping MDT, existing lesions inflamed, often tender nerves, rapid response to steroids (2–4 weeks), BI not rising", "Relapse: insidious onset, usually >3 years after RFT, new lesions slowly, no response to steroid trial, BI rises/solid bacilli"]),
 ("What are persisters and resisters?", ["Persisters: drug-sensitive but dormant viable bacilli that survive despite therapy (in nerves, smooth muscle, bone marrow) — cause late relapse", "Resisters: genetically drug-resistant bacilli (mutations in rpoB, folP1, gyrA) — primary or secondary (after monotherapy)"]),
 ("How is the eye involved?", ["Lagophthalmos (facial nerve, zygomatic branch — in reactions), corneal anaesthesia (trigeminal) → exposure keratitis and ulcer", "Madarosis, iridocyclitis (acute in ENL, chronic in LL), scleritis, iris pearls, cataract, secondary glaucoma", "Vision loss → grade 2 disability; needs eye exercises, goggles, tarsorrhaphy if severe"]),
 ("Systemic involvement in lepromatous leprosy?", ["Nose: stuffiness, epistaxis, septal perforation, saddle nose", "Testes: atrophy → infertility, gynaecomastia", "Bones: absorption of phalanges, maxilla (facies leprosa); osteoporosis", "Kidney: amyloidosis, glomerulonephritis (ENL); liver, lymph nodes, larynx (hoarseness)"]),
 ("What is the role of reconstructive surgery? (short note)", ["Only after disease and reactions are inactive for ≥6 months", "Tendon transfers: claw hand — Brand's procedures/lasso; foot drop — tibialis posterior transfer; ape thumb — opponensplasty", "Eyebrow reconstruction (hair grafts), nasal reconstruction, tarsorrhaphy for lagophthalmos; nerve decompression for abscess/neuritis"]),
 ("Prevention of disability and care of anaesthetic hands/feet?", ["Soak, scrape (oil), oil daily for dry skin; inspect for cracks and wounds; protective footwear (MCR micro-cellular rubber chappals), avoid hot objects", "Self-care groups; splints and physiotherapy for weak muscles; early steroid for neuritis", "Ulcer: rest, cleaning, dressing, offloading; avoid walking on ulcerated foot"]),
 ("Differential diagnosis of hypopigmented patches (common short note).", ["Pityriasis alba, pityriasis versicolor, nevus depigmentosus/anaemicus, post-inflammatory hypopigmentation, vitiligo (depigmented), indeterminate leprosy, hypopigmented mycosis fungoides, idiopathic guttate hypomelanosis, progressive macular hypomelanosis, sarcoidosis, PKDL (post-kala-azar)", "Sensation, nerve thickening and smear help separate leprosy"]),
 ("Differential diagnosis of nodular lesions as in LL.", ["PKDL (no sensory loss, LD bodies), neurofibromatosis, cutaneous leishmaniasis, sarcoidosis, lymphoma/leukaemia cutis, xanthomas, secondary syphilis, multiple histiocytomas, Kaposi sarcoma, onchocerciasis"]),
 ("Leprosy elimination status in India?", ["Elimination as a public health problem (prevalence <1/10,000) achieved nationally in December 2005; some districts still above", "National Strategic Plan aims at interruption of transmission / zero new cases by 2027 (SDG target 2030)", "Indicators: new case detection rate, grade 2 disability per million, child proportion"]),
 ],
 spot=["Cardinal signs — anaesthetic patch, thick nerve, positive smear (any one)", "Lucio phenomenon — diffuse LL + necrotic angular ulcers without fever", "Histoid — shiny nodules, spindle cells, very high BI"],
 note="Doses and duration follow the NLEP revised regimen (effective 1 April 2025) as already used in Exam drugs; check with the department for local practice."),

dict(case="Cutaneous tuberculosis", src=f"{PYQ}; {IA} ch. 16 (Cutaneous tuberculosis); NTEP (India) treatment guidance",
 qa=[
 ("What is cutaneous tuberculosis? How common is it?", ["Infection of skin by M. tuberculosis (rarely M. bovis, BCG) — about 0.1–1% of dermatology patients in India; ~1–2% of extrapulmonary TB", "Commonest Indian forms: lupus vulgaris (adults) and scrofuloderma (children)"]),
 ("Classify cutaneous TB (asked very often).", ["True (bacilli in skin): primary — tuberculous chancre (inoculation in a non-immune person); secondary (prior immunity) — lupus vulgaris (haematogenous/lymphatic or exogenous), tuberculosis verrucosa cutis (exogenous re-inoculation), scrofuloderma (contiguous spread), orificial TB (autoinoculation), tuberculous gumma/metastatic abscess (haematogenous), acute miliary TB", "Tuberculids (no bacilli; hypersensitivity): lichen scrofulosorum, papulonecrotic tuberculid, erythema induratum of Bazin (nodular), ± erythema nodosum/nodular tuberculid", "Also classified by bacillary load: multibacillary (chancre, scrofuloderma, orificial, miliary, gumma) vs paucibacillary (LV, TBVC)"]),
 ("How does host immunity decide the clinical form?", ["High immunity: TBVC, LV, tuberculids (few bacilli, strong tuberculin)", "Low immunity: miliary, orificial, gumma in malnourished/immunosuppressed; scrofuloderma intermediate", "Th1/Th17 polarisation → localised disease; Th2/Treg → disseminated"]),
 ("Describe lupus vulgaris.", ["Chronic progressive paucibacillary form in previously sensitised person; in India mostly on buttocks, trunk, limbs (face in the West)", "Soft reddish-brown plaques that spread at one edge and scar at the other; apple-jelly nodules on diascopy", "Types: plaque (commonest), ulcerative, vegetating, hypertrophic/tumid, papulonodular, sporotrichoid", "Complications: scarring, contractures, mutilation (nose, ear), squamous cell carcinoma in old scars (lupus carcinoma)"]),
 ("What is diascopy and its significance?", ["Pressing a glass slide on the lesion blanches erythema to show the yellow-brown 'apple-jelly' colour of granulomas", "Seen in lupus vulgaris, sarcoidosis, granulomatous rosacea, lupus miliaris disseminatus faciei, leishmaniasis, tuberculoid leprosy"]),
 ("Describe tuberculosis verrucosa cutis (TBVC).", ["Exogenous re-infection in an immune host — 'prosector's wart', 'butcher's wart'; on hands, knees, ankles, buttocks of barefoot walkers and those who sit on the ground", "Warty plaque with irregular edge, fissures that may ooze pus on pressure; slow peripheral spread, central healing with atrophic scar", "Histology: pseudoepitheliomatous hyperplasia, hyperkeratosis, abscesses in upper dermis, tuberculoid granulomas deeper"]),
 ("Describe scrofuloderma.", ["Direct extension from an underlying tuberculous focus — cervical lymph node (commonest), bone, joint, epididymis", "Firm painless subcutaneous swelling → cold abscess → breaks to form undermined ulcers and sinuses discharging cheesy material; bridged (cord-like) scars", "Children and young adults; tuberculin strongly positive; bacilli may be found in pus"]),
 ("Differential diagnosis of scrofuloderma.", ["Atypical mycobacterial lymphadenitis, actinomycosis (sulphur granules), mycetoma, sporotrichosis, hidradenitis suppurativa (axilla/groin), lymphogranuloma venereum (inguinal), syphilitic gumma, deep fungal infection, pyogenic abscess, branchial cyst sinus"]),
 ("Differential diagnosis of lupus vulgaris.", ["Tuberculoid leprosy (anaesthesia, nerve), sarcoidosis, discoid lupus (follicular plugs, atrophy), chromoblastomycosis, leishmaniasis, psoriasis (plaque LV), tertiary syphilis (serpiginous, gumma), deep fungal infection, Bowen's disease, granuloma annulare, tinea (KOH)"]),
 ("What is tuberculous chancre?", ["Primary inoculation in a non-immune person (child) after trauma — injection, circumcision, ear piercing, tattooing", "Painless papulonodule → firm shallow ulcer with granular base after 2–3 weeks + marked regional lymphadenopathy (tuberculous primary complex of skin)", "Tuberculin negative at first, converts later; bacilli plentiful; differential: sporotrichosis, cat-scratch disease, primary syphilis, atypical mycobacteria"]),
 ("What is orificial tuberculosis?", ["Painful shallow ulcers at mouth, anus, genitals — autoinoculation from advanced internal TB (lung, intestine, urinary) in a poorly immune host; bacilli many; poor prognosis"]),
 ("What is a tuberculous gumma (metastatic tuberculous abscess)?", ["Haematogenous spread in immunosuppressed/malnourished children → firm subcutaneous nodules on trunk/limbs which break down into ulcers and sinuses"]),
 ("Define tuberculids and list the criteria.", ["Skin eruptions associated with TB elsewhere, thought to be hypersensitivity to bacilli or antigens", "Criteria: typical clinical and histological picture; no bacilli by stain/culture (PCR may be positive); strongly positive Mantoux/IGRA; evidence of present or past TB; response to ATT"]),
 ("Describe lichen scrofulosorum.", ["Grouped asymptomatic tiny follicular/perifollicular yellow-brown lichenoid papules on the trunk of children/young adults, often with tuberculous lymph nodes or bone", "Histology: superficial non-caseating granulomas around follicles and sweat ducts", "Differential: lichen nitidus, keratosis pilaris, lichenoid sarcoid, frictional lichenoid eruption"]),
 ("Describe papulonecrotic tuberculid.", ["Symmetrical crops of dusky red papules with central necrosis/crust on extensor limbs, knees, elbows, ears, buttocks; heal with varioliform scars", "Histology: wedge-shaped dermal necrosis with vasculitis (leukocytoclastic or granulomatous)", "Differential: PLEVA, lymphomatoid papulosis, perforating disorders, secondary syphilis, prurigo"]),
 ("Describe erythema induratum of Bazin.", ["Recurrent tender deep nodules on the backs of calves of young/middle-aged women; may ulcerate and scar", "Lobular panniculitis with vasculitis, caseation and granulomas", "Nodular vasculitis = non-TB counterpart; differential: erythema nodosum (shins, no ulceration, septal panniculitis), polyarteritis nodosa"]),
 ("How will you investigate cutaneous TB?", ["Histopathology (tuberculoid granulomas ± caseation) and tissue culture — ideally two biopsies: one for HPE, one for culture/CBNAAT", "Ziehl–Neelsen stain (low yield in paucibacillary forms); culture — LJ medium (4–8 weeks) or liquid MGIT (faster, more sensitive), with drug-susceptibility testing", "CBNAAT/GeneXpert MTB/RIF (rifampicin resistance in ~2 h) and TrueNat — recommended by NTEP; PCR (IS6110) helpful in paucibacillary forms", "Mantoux test (strongly positive in LV, TBVC, tuberculids) and IGRA (QuantiFERON) — support, not diagnose", "Look for systemic focus: chest X-ray, ultrasound abdomen, FNAC of nodes, sputum; HIV test, blood sugar"]),
 ("How do you read a Mantoux test?", ["0.1 ml (5 TU PPD-S or 2 TU PPD RT23) intradermally on volar forearm, read at 48–72 h as transverse diameter of induration", "≥10 mm positive in general population; ≥5 mm in HIV/immunosuppressed; very strong (≥15 mm or vesiculation) in tuberculids/LV", "False negative: anergy, HIV, malnutrition, miliary TB, measles, steroids; false positive: BCG, NTM"]),
 ("What is a therapeutic trial and when is it justified?", ["When clinical suspicion is strong but bacteriology and histology are inconclusive", "Full four-drug daily regimen for 5–6 weeks; definite improvement supports TB — no response should prompt re-evaluation for other causes", "Use judiciously because of drug toxicity and risk of resistance"]),
 ("What is the treatment of cutaneous TB (NTEP)?", ["Same as extra-pulmonary TB — daily fixed-dose combination by weight band", "Intensive phase 2 months: isoniazid + rifampicin + pyrazinamide + ethambutol (HRZE); continuation phase 4 months: HRE (isoniazid, rifampicin, ethambutol) — total 6 months; may be extended (e.g. to 9–12 months) by the clinician for slow response or associated bone/CNS disease", "Drug-resistant TB (rifampicin resistance on CBNAAT): refer for NTEP DR-TB regimens (e.g. BPaLM — bedaquiline, pretomanid, linezolid, moxifloxacin — 6 months)", "Pyridoxine with INH; check LFT; Nikshay registration and Ni-kshay Poshan Yojana nutrition support; surgical excision for small LV, plastic repair later"]),
 ("Major side effects of first-line ATT?", ["Isoniazid: hepatitis, peripheral neuropathy (prevent with pyridoxine), pellagra, lupus-like syndrome, acneiform rash", "Rifampicin: hepatitis, orange discolouration of secretions, flu-like illness, thrombocytopenia, drug interactions", "Pyrazinamide: hepatotoxicity, hyperuricaemia/gout, photosensitivity", "Ethambutol: optic neuritis (red–green colour vision), hypersensitivity", "Cutaneous drug reactions: commonest culprit — first-line drugs cause maculopapular rash, DRESS, SJS/TEN, lichenoid eruption, FDE"]),
 ("How do you assess response to treatment?", ["Clinical: lesions flatten and stop spreading in 4–6 weeks; ulcers heal; sinus discharge stops", "Most heal by the end of 6 months; residual scarring is common"]),
 ("What is BCG-related skin disease?", ["Normal: papule → ulcer → scar in 6–12 weeks", "Complications: local abscess, regional lymphadenitis (suppurative), lupus vulgaris at site, keloid, disseminated BCG-osis in immunodeficiency (SCID, HIV)", "BCG reactivation at injection site in Kawasaki disease"]),
 ("What is the difference between atypical mycobacterial infection and TB of skin?", ["NTM (M. marinum — fish-tank granuloma, sporotrichoid nodules on hand; M. ulcerans — Buruli ulcer; M. fortuitum/chelonae/abscessus — post-procedure abscesses after injections, liposuction, pedicure)", "NTM: from environment, not person-to-person; often resistant to standard ATT — needs clarithromycin, doxycycline, rifampicin/ethambutol, amikacin by species"]),
 ("Histopathology of lupus vulgaris?", ["Tuberculoid granulomas (epithelioid cells, Langhans giant cells, lymphocytes) in upper and mid dermis, usually with little or no caseation", "Epidermis may be atrophic, ulcerated or hyperplastic; AFB rarely seen"]),
 ("Why is scrofuloderma classed as multibacillary but tuberculids as having no bacilli?", ["Scrofuloderma: direct spread from a bacilli-rich deep focus with intermediate immunity", "Tuberculids: strong immunity clears organisms, leaving immune-mediated inflammation (antigen/DNA may be detected by PCR)"]),
 ("How do you differentiate lupus vulgaris from sarcoidosis clinically and on histology?", ["Clinical: LV is unilateral, slowly spreading, with scarring and ulceration; sarcoid is often symmetrical, non-ulcerating, with systemic features", "Histology: LV has tuberculoid granulomas with dense lymphocytes, sometimes caseation; sarcoid has 'naked' granulomas with sparse lymphocytes, no caseation", "Mantoux: LV strongly positive; sarcoid often negative (anergy)"]),
 ("Prognosis?", ["Excellent with full ATT; complications only from delay — scarring, deformities, SCC in long-standing lupus vulgaris"]),
 ],
 spot=["Apple-jelly nodules on diascopy — lupus vulgaris (also sarcoid)", "Sinus + undermined ulcer + bridge scars over neck nodes — scrofuloderma", "Warty plaque on the knee of barefoot worker — TBVC"]),

dict(case="Herpes simplex", src=f"{PYQ}; {IA} (Viral infections); CDC STI treatment guidelines 2021 for antiviral doses",
 qa=[
 ("What is the causative agent and classification of HSV?", ["Herpes simplex virus type 1 and 2 — human herpesvirus 1 and 2; alpha-herpesviruses (enveloped, double-stranded DNA)", "HSV-1 mainly orolabial (now also many genital first episodes); HSV-2 mainly genital and neonatal; both stay latent in sensory ganglia (trigeminal for HSV-1, sacral for HSV-2)"]),
 ("Name the 8 human herpesviruses and their diseases (very common question).", ["HHV-1 (HSV-1): orolabial herpes, keratitis, encephalitis; HHV-2 (HSV-2): genital and neonatal herpes", "HHV-3 (VZV): varicella, zoster", "HHV-4 (EBV): infectious mononucleosis, oral hairy leukoplakia, Burkitt and nasopharyngeal carcinoma, Gianotti–Crosti, hydroa vacciniforme-like lymphoma", "HHV-5 (CMV): perianal ulcers in HIV, congenital infection ('blueberry muffin'), mononucleosis", "HHV-6 and 7: roseola infantum (exanthem subitum); HHV-6 reactivation in DRESS; HHV-7 linked to pityriasis rosea", "HHV-8: Kaposi sarcoma, primary effusion lymphoma, multicentric Castleman disease"]),
 ("Describe the pathogenesis and latency.", ["Entry through mucosa/abraded skin → replication in epidermis → retrograde axonal transport to sensory ganglion → latent (latency-associated transcripts) → reactivation with triggers travels back to skin", "Triggers: fever, UV light, menstruation, stress, trauma, immunosuppression", "Asymptomatic shedding is the main source of transmission"]),
 ("Describe primary herpetic gingivostomatitis.", ["Usually HSV-1 in children 1–5 years; fever, malaise, painful vesicles that erode on gums, tongue, palate, lips; swollen bleeding gums; drooling; tender cervical nodes", "Resolves in ~2 weeks; oral acyclovir within 72–96 h shortens it"]),
 ("Describe recurrent herpes labialis.", ["Prodrome of tingling/burning for hours → grouped vesicles on an erythematous base at vermilion border → pustules, crusts; heals in 7–10 days without scar", "Same site each time"]),
 ("Clinical features of genital herpes.", ["First episode primary: multiple painful bilateral vesicles/erosions with fever, inguinal lymphadenopathy, dysuria; lasts 2–3 weeks; may cause aseptic meningitis, urinary retention (sacral radiculopathy)", "Recurrent: fewer, unilateral, shorter (5–10 days), less painful; HSV-2 recurs more than HSV-1", "Atypical: fissures, erythema only, in HIV — chronic deep ulcers"]),
 ("What is the Tzanck smear and what does it show?", ["Scraping from the base of a fresh vesicle stained with Giemsa", "Multinucleated giant cells with nuclear moulding, margination of chromatin, and intranuclear (Cowdry A) inclusions; also acantholytic ballooned cells", "Cannot distinguish HSV from VZV; low sensitivity — PCR is now the test of choice"]),
 ("Investigations for herpes?", ["PCR of vesicle fluid/swab — most sensitive and specific; typing HSV-1 vs 2", "Viral culture (declining use), direct immunofluorescence", "Type-specific serology (glycoprotein G) to detect past infection or counsel discordant couples — not for diagnosis of an active ulcer", "Screen for other STIs incl. HIV and syphilis in genital herpes"]),
 ("Give the differential diagnosis of genital ulcer.", ["Painful: herpes (multiple grouped small), chancroid (ragged undermined purulent ulcer, painful suppurative bubo), traumatic, Behçet's, fixed drug eruption (recurrent same site), aphthae", "Painless: primary syphilis (indurated clean ulcer, rubbery nodes), donovanosis (beefy red, bleeds, pseudobubo), LGV (transient ulcer, then bubo with groove sign)"]),
 ("Treatment of first episode genital herpes.", ["Acyclovir 400 mg three times daily for 7–10 days (or 200 mg five times daily); valacyclovir 1 g twice daily 7–10 days; famciclovir 250 mg thrice daily", "Saline baths, analgesics, lidocaine gel; abstain from sex during lesions"]),
 ("Treatment of recurrences and suppressive therapy.", ["Episodic: start within 24 h of prodrome — acyclovir 800 mg three times daily for 2 days, or 800 mg twice daily 5 days; valacyclovir 500 mg twice daily 3 days or 1 g daily 5 days; famciclovir 1 g twice daily for 1 day", "Suppressive (≥6 recurrences/year, severe, psychological distress, discordant partner): acyclovir 400 mg twice daily or valacyclovir 500 mg–1 g once daily; review yearly"]),
 ("What is the mechanism of acyclovir? (short note)", ["Guanosine analogue phosphorylated first by viral thymidine kinase (so active only in infected cells) then by cellular kinases to the triphosphate, which inhibits viral DNA polymerase and terminates DNA chain", "Poor oral bioavailability (~15–20%); valacyclovir prodrug gives 3–5 times higher levels", "Side effects: nausea, headache; IV — crystalline nephropathy (hydrate well), neurotoxicity in renal failure", "Resistance (thymidine kinase mutation) in immunocompromised — use foscarnet or cidofovir"]),
 ("What is eczema herpeticum (Kaposi's varicelliform eruption)?", ["Widespread HSV infection on skin with an existing dermatosis (atopic dermatitis commonest, Darier's disease, pemphigus, burns, Hailey–Hailey, CTCL)", "Clusters of monomorphic punched-out haemorrhagic erosions and vesicles, fever, lymphadenopathy", "Dermatological emergency — oral/IV acyclovir; check eye involvement; risk of viraemia"]),
 ("What is herpetic whitlow?", ["HSV infection of the finger — children with gingivostomatitis (thumb-sucking) and health workers; painful deep vesicles on fingertip", "Do not incise (confused with bacterial paronychia/felon)"]),
 ("Name other clinical patterns of HSV infection.", ["Herpes gladiatorum (wrestlers), herpetic keratitis/keratoconjunctivitis, herpetic sycosis (beard), lumbosacral herpes", "Neonatal herpes (skin-eye-mouth, CNS, disseminated) — mother with primary genital herpes near delivery; caesarean if lesions at labour", "HSV-associated erythema multiforme (commonest cause of recurrent EM) — suppressive acyclovir prevents it", "HSV encephalitis (temporal lobe); chronic ulcerative herpes in HIV (CD4 <100) — an AIDS-defining illness if >1 month"]),
 ("How do you manage herpes in pregnancy?", ["Primary infection in third trimester → highest neonatal risk: acyclovir, and caesarean section", "Recurrent herpes: suppressive acyclovir from 36 weeks; caesarean only if lesions/prodrome at labour", "Acyclovir is safe in pregnancy"]),
 ("Counselling points for genital herpes?", ["Lifelong infection but recurrences become fewer with time", "Transmission can occur without lesions; condoms and suppressive therapy reduce (not eliminate) risk; inform partners", "Genital herpes increases risk of acquiring and transmitting HIV"]),
 ],
 spot=["Grouped vesicles on red base, same site each time — recurrent HSV", "Tzanck: multinucleated giant cells with nuclear moulding (HSV/VZV, not distinguishable)", "Punched-out erosions on atopic skin with fever — eczema herpeticum"]),

dict(case="Molluscum contagiosum", src=f"{PYQ}; {IA} (Viral infections)",
 qa=[
 ("What is molluscum contagiosum?", ["Common benign self-limiting infection of the epidermis by molluscum contagiosum virus (poxvirus, genus Molluscipoxvirus; MCV-1 commonest, MCV-2 more in adults/HIV)", "Largest DNA virus pathogenic to humans; replicates in the cytoplasm"]),
 ("Who gets it and how does it spread?", ["Children (direct contact, shared towels, swimming pools), sexually active adults (genital/pubic area), immunosuppressed (HIV, transplant) and atopic children", "Autoinoculation by scratching (Koebner) and shaving"]),
 ("Describe the lesion.", ["Firm, smooth, pearly white or skin-coloured dome-shaped papules 2–5 mm with central umbilication; cheesy core can be expressed", "Children: trunk, flexures, face, limbs; adults: genitals, thighs, lower abdomen", "Giant molluscum (>1 cm), and many facial lesions — think HIV (CD4 <100)", "Molluscum dermatitis (eczema around lesions), 'BOTE' sign — inflamed lesions (Beginning Of The End) signalling regression"]),
 ("What are molluscum bodies?", ["Large eosinophilic intracytoplasmic inclusion bodies (Henderson–Paterson bodies) in the keratinocytes of a lobulated, cup-shaped, endophytic epidermal proliferation", "Seen on squash smear of the expressed core (Giemsa/Wright) or biopsy"]),
 ("Differential diagnosis?", ["Warts (no umbilication), milia, syringoma, sebaceous hyperplasia (adults, face), keratoacanthoma and BCC (single large lesion), epidermoid cyst", "In HIV: cryptococcosis, histoplasmosis, penicilliosis (talaromycosis) — umbilicated papules on face; must do smear/biopsy", "Varicella (early), juvenile xanthogranuloma, Spitz naevus"]),
 ("How do you investigate?", ["Clinical (dermoscopy shows central white-yellow polylobular structure with crown of peripheral vessels)", "Squash preparation for molluscum bodies; biopsy for atypical lesions", "In adults with genital lesions — screen for HIV and other STIs; in extensive facial lesions — HIV test"]),
 ("Treatment options.", ["Watchful waiting in children (usually clears in 6–18 months; immunity develops)", "Physical: curettage, enucleation/expression with a needle (with topical anaesthetic), cryotherapy, electrocautery, laser (pulsed dye)", "Chemical: 10–20% KOH solution, cantharidin 0.7% (FDA-approved for molluscum in 2023), podophyllotoxin (adults, not in pregnancy), tretinoin, salicylic acid, trichloroacetic acid; berdazimer gel (nitric oxide donor, FDA 2024)", "Imiquimod is no longer favoured in children (trials showed no benefit)", "HIV: ART (immune reconstitution clears them); cidofovir in refractory"]),
 ("Why treat genital molluscum in adults?", ["To prevent sexual transmission and autoinoculation, and it signals sexual exposure (screen for STIs)"]),
 ("What is the course and prognosis?", ["Each lesion lasts ~2 months; the infection lasts months to years; heals without scars unless treated aggressively or secondarily infected", "Recurrence common; immunosuppressed — persistent, extensive lesions"]),
 ("What is molluscum dermatitis and how do you manage it?", ["Eczematous patch around molluscum lesions (often signals immune response); treat with mild topical steroid/emollient; it often precedes clearance"]),
 ("Which poxviruses affect human skin?", ["Molluscipoxvirus — molluscum contagiosum", "Orthopoxvirus — smallpox (eradicated), vaccinia, cowpox, mpox (monkeypox — 2022 global outbreak; umbilicated pustules on genitals, lymphadenopathy, tecovirimat)", "Parapoxvirus — orf, milker's nodule", "Yatapoxvirus — tanapox"]),
 ],
 spot=["Pearly umbilicated papules with cheesy core — molluscum", "Henderson–Paterson bodies (molluscum bodies)", "Many giant facial mollusca — test for HIV; rule out cryptococcosis/histoplasmosis"],
 note="Cantharidin (2023) and berdazimer (2024) approvals are newer than the textbooks — please confirm before using in a viva."),

dict(case="Chickenpox (varicella)", src=f"{PYQ}; {IA} (Viral infections); national immunisation guidance (IAP)",
 qa=[
 ("What is chickenpox? Agent and transmission?", ["Primary infection with varicella-zoster virus (HHV-3, alpha-herpesvirus)", "Spread by respiratory droplets/aerosols and direct contact with vesicle fluid; highly contagious (secondary attack rate ~90% in susceptible household contacts)", "Incubation 10–21 days (average 14–16); infectious from 1–2 days before rash until all lesions are crusted (~5–7 days)"]),
 ("Describe the pathogenesis.", ["Inhalation → replication in the respiratory tract and regional nodes → primary viraemia → liver/spleen → secondary viraemia → skin (in waves → crops)", "Virus then remains latent in dorsal root and cranial nerve ganglia → may reactivate later as herpes zoster"]),
 ("Describe the rash.", ["Mild prodrome (fever, malaise) in adults, often none in children", "Itchy rash starts on the scalp/face and trunk (centripetal distribution) and spreads to limbs; mucosae may have erosions", "Evolution: macule → papule → vesicle ('dewdrop on a rose petal') → pustule → crust within 24 h; lesions in all stages at the same time (pleomorphism) due to crops over 3–5 days", "Heals in 1–2 weeks; may leave scars (especially if scratched/infected)"]),
 ("Differentiate chickenpox from smallpox.", ["Chickenpox: centripetal, superficial thin-walled vesicles, lesions in different stages, mild fever, palms/soles spared, no prodromal severe toxaemia", "Smallpox: centrifugal (face and extremities incl. palms/soles), deep-seated firm vesicles/pustules, all lesions at same stage, severe prodrome; now eradicated (1980)"]),
 ("Other differentials?", ["Disseminated herpes simplex or zoster, eczema herpeticum, hand-foot-mouth disease (coxsackie — palms, soles, mouth), insect bite reactions/papular urticaria, PLEVA, impetigo, scabies with pyoderma, drug eruptions (AGEP), rickettsial pox, mpox"]),
 ("What are the complications?", ["Commonest in children: secondary bacterial infection (S. aureus, group A strep — cellulitis, necrotising fasciitis, toxic shock)", "Pneumonia (commonest serious complication in adults, smokers and pregnant women)", "CNS: acute cerebellar ataxia (children), encephalitis, Reye's syndrome (with aspirin — avoid aspirin), Guillain–Barré", "Haemorrhagic varicella (purpura fulminans), hepatitis, myocarditis, nephritis, arthritis, thrombocytopenia", "Immunocompromised: progressive disseminated varicella with high mortality"]),
 ("Discuss varicella in pregnancy.", ["Mother: higher risk of severe varicella pneumonia", "Congenital (fetal) varicella syndrome — infection in the first 20 weeks (risk ~1–2%): cicatricial skin scars in dermatomal distribution, limb hypoplasia, eye defects (chorioretinitis, cataract), microcephaly, low birth weight", "Neonatal varicella: mother develops rash 5 days before to 2 days after delivery → severe disease in baby (no maternal antibodies) — give VZIG to the baby and acyclovir if disease develops", "Exposure of non-immune pregnant woman: VZIG within 10 days; acyclovir if rash develops"]),
 ("How will you investigate?", ["Clinical diagnosis usually", "Tzanck smear (multinucleated giant cells — not specific)", "PCR of vesicle fluid (best), DFA; serology IgM/IgG (immunity status)", "CBC, LFT, chest X-ray if pneumonia suspected"]),
 ("Treatment of chickenpox.", ["Healthy children: symptomatic — calamine lotion, oral antihistamines, paracetamol (no aspirin — Reye's), trimmed nails, hygiene", "Oral acyclovir 20 mg/kg (max 800 mg) four times daily for 5 days if started within 24 h — for adolescents >12 y, adults, chronic skin/lung disease, on steroids, secondary household cases", "Adults: acyclovir 800 mg five times a day for 7 days or valacyclovir 1 g thrice daily for 7 days", "IV acyclovir 10 mg/kg every 8 h for immunocompromised, pneumonia, encephalitis, pregnancy with complications"]),
 ("What is the varicella vaccine?", ["Live attenuated Oka strain", "IAP schedule (India): 2 doses — 15 months and 4–6 years (catch-up: 2 doses ≥3 months apart in children <13 y, 4 weeks apart ≥13 y); not in the national (UIP) schedule", "Contraindicated in pregnancy and severe immunosuppression; avoid pregnancy for 1 month after", "Post-exposure: vaccine within 3–5 days; VZIG (within 10 days) for immunocompromised, pregnant non-immune, neonates"]),
 ("What is breakthrough varicella?", ["Varicella >42 days after vaccination — mild, few lesions (often <50), mostly papular rather than vesicular, low fever — still contagious"]),
 ("Discuss the isolation advice.", ["Exclude from school/work until all lesions crust (about 5–7 days after onset)", "Hospital: airborne and contact precautions; non-immune health workers exposed should avoid patient contact from day 8 to day 21 after exposure"]),
 ("Why are adults sicker than children?", ["More vigorous immune (cell-mediated) response and more pneumonia; smoking and pregnancy increase risk"]),
 ("What is the link between varicella and zoster?", ["Same virus — chickenpox is primary infection; zoster is reactivation of latent VZV in a sensory ganglion when cell-mediated immunity falls (age, HIV, malignancy)", "Zoster lesions can transmit chickenpox (not zoster) to non-immune contacts"]),
 ("What is Ramsay Hunt syndrome? (often linked question)", ["Zoster of the geniculate ganglion — ipsilateral facial palsy + ear pain + vesicles in the ear canal/pinna ± anterior-tongue taste loss, tinnitus, vertigo", "Treat with antivirals and steroids early"]),
 ],
 spot=["Lesions in all stages at once, centripetal — chickenpox", "'Dewdrop on a rose petal' vesicle", "Avoid aspirin — Reye's syndrome"],
 note="Vaccine schedule follows IAP recommendations; confirm the current IAP schedule before use."),
]
